<?php
declare(strict_types=1);
namespace App\Infrastructure\Persistence\Doctrine\Study;
use App\Domain\Study\Entity\DirectedStudyPlan;use App\Domain\Study\Repository\DirectedStudyPlanRepositoryInterface;use App\Infrastructure\Persistence\Doctrine\Study\Entity\DirectedStudyPlanRecord;use Doctrine\ORM\EntityManagerInterface;
final class DoctrineDirectedStudyPlanRepository implements DirectedStudyPlanRepositoryInterface { public function __construct(private readonly EntityManagerInterface $em){} public function save(DirectedStudyPlan $plan):void{$r=$this->em->find(DirectedStudyPlanRecord::class,$plan->id)??new DirectedStudyPlanRecord();$r->id=$plan->id;$r->userId=$plan->userId;$r->examId=$plan->examId;$r->positionId=$plan->positionId;$r->name=$plan->name;$r->createdAt=$plan->createdAt;$r->updatedAt=$plan->updatedAt;$this->em->persist($r);} public function listForUser(string $userId):array{return array_map($this->map(...),$this->em->createQueryBuilder()->select('p')->from(DirectedStudyPlanRecord::class,'p')->where('p.userId=:user')->setParameter('user',$userId)->orderBy('p.updatedAt','DESC')->getQuery()->getResult());} public function findForUser(string $id,string $userId):?DirectedStudyPlan{$r=$this->em->find(DirectedStudyPlanRecord::class,$id);return $r instanceof DirectedStudyPlanRecord&&$r->userId===$userId?$this->map($r):null;} private function map(DirectedStudyPlanRecord $r):DirectedStudyPlan{return new DirectedStudyPlan($r->id,$r->userId,$r->examId,$r->positionId,$r->name,$r->createdAt,$r->updatedAt);} }
